actionFn:
const { text } = params;
const summaryPrompt = services.prompt.usePrompt("Summarize Text", {
  text,
  maxSentences: 2
});
if (!summaryPrompt) {
  throw new Error('Prompt "Summarize Text" not found \u2014 import compiled-prompts.json first');
}
const summaryResult = await services.llm.generateText({
  model: { provider: "openai", model: "gpt-4o" },
  prompt: summaryPrompt
});
const classifyPrompt = services.prompt.usePrompt("Classify Intent", {
  message: text,
  categories: ["question", "request", "feedback", "complaint"]
});
if (!classifyPrompt) {
  throw new Error('Prompt "Classify Intent" not found \u2014 import compiled-prompts.json first');
}
const ClassificationSchema = z.object({
  intent: z.string(),
  confidence: z.number()
});
const classifyResult = await services.llm.generateObject({
  model: { provider: "openai", model: "gpt-4o" },
  schema: ClassificationSchema,
  prompt: classifyPrompt
});
const classification = classifyResult.object;
services.logger.info("Text analysis complete", {
  summary: summaryResult.text,
  classification
});
return {
  summary: summaryResult.text,
  intent: classification.intent,
  confidence: classification.confidence
};

const ASSISTANT_BIRTH_ROLE = services.database.EARS.RoleKind.Custom("assistant_birth");
const existingBirthThreadId = services.database.qx().withRole(ASSISTANT_BIRTH_ROLE).first();
if (existingBirthThreadId) {
  await services.logger.info("Birth thread already exists", {
    threadId: existingBirthThreadId
  });
  return {
    threadId: existingBirthThreadId,
    success: true,
    created: false
  };
}
const { id: threadId, shortCode, timestamp, status } = services.chat.createThreadAndNotify({
  topic: "Assistant Birth",
  instructions: "Welcome! This thread will help you get started with your new assistant.",
  tags: [],
  role: ASSISTANT_BIRTH_ROLE,
  forcedMode: "birth"
});
const { artifactId: todoArtifactId } = services.artifact.createAndNotify({
  artifactType: "todo",
  title: "Getting Started Tasks",
  content: {
    tasks: [
      { id: "1", description: "Give your assistant a name", completed: false },
      { id: "2", description: "Share your technical skill level", completed: false },
      { id: "3", description: "Discuss projects you're working on", completed: false }
    ],
    status: "pending"
  },
  threadId
});
const { artifactId: workspaceArtifactId } = services.artifact.createAndNotify({
  artifactType: "project",
  title: "My Projects",
  content: {},
  threadId
});
services.chat.openThreadChatAndRefreshRecent(threadId);
await services.logger.info("Birth thread created and activated", {
  threadId,
  shortCode,
  todoArtifactId,
  workspaceArtifactId
});
return {
  threadId,
  shortCode,
  timestamp,
  status,
  todoArtifactId,
  workspaceArtifactId,
  success: true,
  created: true
};

const { dbPrompt } = params;
try {
  services.emitter.sendToPlugin("database", { type: "MAGIC_PROMPT_LOADING" });
  const [doc1, doc2] = await Promise.all([
    services.library.getDocByCode("DOC-1"),
    services.library.getDocByCode("DOC-2")
  ]);
  services.logger.info("db example docs", { dbPrompt, doc1, doc2 });
  if (!doc1) {
    throw new Error("Document DOC-1 not found");
  }
  if (!doc2) {
    throw new Error("Document DOC-2 not found");
  }
  const queryDoc = doc1.content;
  const transactionDoc = doc2.content;
  const queryExamples = queryDoc[0]?.text || "No content found in DOC-1";
  const transactionExamples = transactionDoc[0]?.text || "No content found in DOC-2";
  const MessageClassificationSchema = z.object({
    type: z.enum(["query", "transaction"]).describe("Whether the message is a read operation (query) or write operation (transaction)")
  });
  const classificationResult = await services.llm.generateObject({
    model: { provider: "openai", model: "gpt-5-nano-2025-08-07" },
    schema: MessageClassificationSchema,
    "reasoning_effort": "minimal",
    prompt: services.prompt.usePrompt("db-query-classification")({
      queryExamples,
      transactionExamples,
      dbPrompt
    }),
    temperature: 0.3
  });
  services.logger.info("classificationResult", classificationResult);
  const classification = classificationResult.object;
  const queryPrompt = queryDoc[1]?.text || "";
  const transactionPrompt = transactionDoc[1]?.text || "";
  const selectedDoc = classification.type === "query" ? queryPrompt : transactionPrompt;
  services.logger.info("Message classified", {
    type: classification.type
  });
  const result = await services.llm.generateText({
    model: {
      provider: "openai",
      model: "gpt-5-nano-2025-08-07"
    },
    "reasoning_effort": "minimal",
    prompt: dbPrompt,
    system: services.prompt.usePrompt("db-query-examples")({
      selectedDoc
    }),
    temperature: 0.7,
    maxTokens: 1e3
  });
  services.emitter.sendToPlugin("database", {
    type: "MAGIC_PROMPT_GENERATED",
    query: result.text
  });
} catch (error) {
  services.logger.error("Error generating database operation", { error });
  services.emitter.sendToPlugin("database", {
    type: "QUERY_ERROR",
    error: error instanceof Error ? error.message : "Unknown error occurred"
  });
}

function buildButtonsWithDeploymentState(deploymentState) {
  return [
    {
      id: "debug-mode",
      label: "Debug Mode",
      state: "off",
      toggleStates: {
        off: { label: "Enable Debug Mode", variant: "secondary" },
        on: { label: "Disable Debug Mode", variant: "success" }
      }
    },
    {
      id: "auto-save",
      label: "Auto Save",
      state: "on",
      toggleStates: {
        on: { label: "Auto Save: ON", variant: "success" },
        off: { label: "Auto Save: OFF", variant: "danger" }
      }
    },
    {
      id: "deployment",
      label: "Deployment",
      state: deploymentState,
      states: {
        ready: { label: "Deploy to Production", variant: "primary" },
        deploying: { label: "Deploying...", variant: "secondary", disabled: true },
        deployed: { label: "Deployed Successfully", variant: "success" },
        failed: { label: "Deployment Failed", variant: "danger" }
      }
    }
  ];
}
function buildMockLinks(threadId) {
  return [
    {
      label: "View Project Plan",
      event: {
        target: "agent",
        data: {
          type: "SELECT_ARTIFACT",
          artifactId: "placeholder"
        }
      },
      icon: "file-text"
    },
    {
      label: "Open Birth Thread",
      event: {
        target: "agent",
        data: {
          type: "OPEN_THREAD_CHAT",
          threadId
        }
      },
      icon: "message-square"
    },
    {
      label: "Go to Threads",
      event: {
        target: "application",
        data: {
          type: "SELECT_PLUGIN",
          pluginId: "threads"
        }
      },
      icon: "settings"
    },
    {
      label: "View Documentation",
      event: {
        target: "external",
        data: {
          url: "https://docs.example.com"
        }
      },
      icon: "external-link"
    }
  ];
}
function simulateDeployment(services, messageId, buildButtons) {
  setTimeout(() => {
    services.chat.updateMessageState(messageId, {
      blocks: [{
        type: "button-group",
        props: {
          buttons: buildButtons("deploying"),
          keepInteractive: true,
          displayText: "Action completed:"
        }
      }]
    });
  }, 2e3);
  setTimeout(() => {
    services.chat.updateMessageState(messageId, {
      blocks: [{
        type: "button-group",
        props: {
          buttons: buildButtons("deployed"),
          keepInteractive: true,
          displayText: "Action completed:"
        }
      }]
    });
  }, 4e3);
}

